def data(n: int, p: int, nc: int):
    X = np.zeros((n, p)); y = np.zeros(n, dtype=int)
    for i in range(n):
        y[i] = i % nc
        for j in range(p):
            v = (i * 7919 + j * 104729 + i * j * 13 + j * j * 3) % 101
            X[i, j] = (v - 50.0) / 25.0 + (0.8 * y[i] if (j + y[i]) % 2 == 0 else -0.3 * y[i])
    return X, y

X, y = data(60, 4, 3)
Q = X[:8] + 0.1
R = 1e-7
A = 1e-9
b2 = y < 2
Xb = X[b2]; yb = y[b2]

check(close(CalibratedClassifierCV(LinearSVC(random_state=0), cv=3).fit(X, y).predict_proba(Q), cal_sig_proba, 1e-6, 1e-8), "cal sigmoid")
check(close(CalibratedClassifierCV(GaussianNB(), method="isotonic", cv=4).fit(X, y).predict_proba(Q), cal_iso_proba, 1e-6, 1e-8), "cal isotonic")
check(close(CalibratedClassifierCV(SVC(), cv=3, ensemble=False).fit(Xb, yb).predict_proba(Q), cal_ne_proba, 1e-6, 1e-8), "cal no ensemble")
sw = 1.0 + (np.arange(60) % 3).astype(float)
check(close(CalibratedClassifierCV(GaussianNB(), cv=3).fit(X, y, sample_weight=sw).predict_proba(Q), cal_sw_proba, 1e-6, 1e-8), "cal sw")
yy = (y > 0).astype(int)
ps = np.abs(np.sin(np.arange(60.0)))
pt, pp = calibration_curve(yy, ps, n_bins=4)
check(close(pt, cc_pt) and close(pp, cc_pp), "calibration_curve")
pt2, pp2 = calibration_curve(yy, ps, n_bins=3, strategy="quantile")
check(close(pt2, ccq_pt) and close(pp2, ccq_pp), "calibration_curve quantile")

